import { connect } from 'node:net'

// The Lambda Node runtime does not bundle a Valkey/Redis client, so this
// speaks the small subset of RESP needed to SET a key with an expiry.
function encodeCommand (...args) {
  let out = `*${args.length}\r\n`
  for (const arg of args) {
    const buffer = Buffer.from(String(arg))
    out += `$${buffer.length}\r\n${buffer}\r\n`
  }
  return out
}

function sendCommand (socket, ...args) {
  return new Promise((resolve, reject) => {
    const onData = (data) => {
      socket.off('error', onError)
      const reply = data.toString()
      reply.startsWith('-') ? reject(new Error(reply.trim())) : resolve(reply.trim())
    }
    const onError = (err) => {
      socket.off('data', onData)
      reject(err)
    }
    socket.once('data', onData)
    socket.once('error', onError)
    socket.write(encodeCommand(...args))
  })
}

function openCache () {
  return new Promise((resolve, reject) => {
    const socket = connect({
      host: process.env.CACHE_ENDPOINT,
      port: Number(process.env.CACHE_PORT || 6379)
    })
    socket.setTimeout(5000, () => socket.destroy(new Error('cache connection timed out')))
    socket.once('connect', () => resolve(socket))
    socket.once('error', reject)
  })
}

async function warm (socket, url, ttl) {
  const response = await fetch(url, {
    headers: { 'User-Agent': 'govuk-cache-warmer' },
    signal: AbortSignal.timeout(30000)
  })

  if (!response.ok) {
    throw new Error(`${url} responded with ${response.status}`)
  }

  const body = await response.text()
  await sendCommand(socket, 'SET', url, body, 'EX', ttl)
}

export const handler = async () => {
  const urls = JSON.parse(process.env.WARM_URLS || '[]')
  const ttl = Number(process.env.CACHE_TTL_SECONDS || 3600)

  if (urls.length === 0) {
    console.log('No URLs configured, nothing to warm')
    return { warmed: 0, failed: 0 }
  }

  const socket = await openCache()
  let warmed = 0
  let failed = 0

  try {
    for (const url of urls) {
      try {
        await warm(socket, url, ttl)
        warmed++
        console.log(`Warmed ${url}`)
      } catch (err) {
        failed++
        console.log(`Failed to warm ${url}: ${err.message}`)
      }
    }
  } finally {
    socket.end()
  }

  console.log(`Warmed ${warmed} URLs, ${failed} failed`)
  return { warmed, failed }
}
EOF

